import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen2Test {

    private static final byte[] SAMPLE_DATA = "Hello World".getBytes();
    private static final int LARGE_SIZE = 1000;





    @Test
    public void testEncodeBase64_ExceedsMaxSize() {
        // Small maxResultSize to trigger IllegalArgumentException
        int maxResultSize = 1; 
        try {
            Base64.encodeBase64(SAMPLE_DATA, false, false, maxResultSize);
            fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Input array too big"));
        }
    }








}

