public class Base64_encodeBase64_TriageGen2Test {

    private static final byte[] SAMPLE_DATA = "Hello World".getBytes();
    private static final int LARGE_SIZE = 1000;







    @Test
    public void testEncodeBase64_StandardEncoding() {
        // isChunked = false, urlSafe = false
        byte[] result = Base64.encodeBase64(SAMPLE_DATA, false, false, LARGE_SIZE);
        String expected = Base64.encodeBase64String(SAMPLE_DATA);
        assertEquals(expected, new String(result));
    }






