package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen2Test {

    private static final byte[] SAMPLE_DATA = "Hello World".getBytes();
    private static final int LARGE_SIZE = 1000;









    @Test
    public void testEncodeBase64_UrlSafeEncoding() {
        // isChunked = false, urlSafe = true
        // Using specific bytes that trigger URL safe characters (+ -> -, / -> _)
        byte[] urlSafeData = new byte[]{(byte) 0xfb, (byte) 0xff, (byte) 0xbf}; 
        byte[] result = Base64.encodeBase64(urlSafeData, false, true, LARGE_SIZE);

        // Verify it matches the standard URL safe method
        byte[] expected = Base64.encodeBase64URLSafe(urlSafeData);
        assertArrayEquals(expected, result);
    }




}

package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen2Test {

    private static final byte[] SAMPLE_DATA = "Hello World".getBytes();
    private static final int LARGE_SIZE = 1000;











    @Test
    public void testEncodeBase64_ChunkedEncoding() {
        // isChunked = true, urlSafe = false
        // We need enough data to trigger chunking if MIME_CHUNK_SIZE is small, 
        // but since we don't know the exact value of MIME_CHUNK_SIZE from the snippet,
        // we test the logic path.
        byte[] chunkedData = new byte[200]; 
        for (int i = 0; i < chunkedData.length; i++) {
            chunkedData[i] = (byte) i;
        }

        byte[] result = Base64.encodeBase64(chunkedData, true, false, 2000);
        assertNotNull(result);
        assertTrue(result.length > 0);
    }


}

